from pwn import *
import time
import base64
import json
import os

# Configuration
HOST = 'crypto.chal.csaw.io'
PORT = 6000
SLEEP_TIME = 0.1
RECONNECT_EVERY = 10
MAX_RETRIES = 3
PROGRESS_FILE = 'progress.json'

context.log_level = 'info'

class PoodleAttack:
    def __init__(self):
        self.conn = None
        self.request_count = 0
        self.decrypted_bytes = {}
        self.load_progress()

    def load_progress(self):
        try:
            if os.path.exists(PROGRESS_FILE):
                with open(PROGRESS_FILE, 'r') as f:
                    self.decrypted_bytes = json.load(f)
        except:
            self.decrypted_bytes = {}

    def save_progress(self):
        with open(PROGRESS_FILE, 'w') as f:
            json.dump(self.decrypted_bytes, f)

    def connect(self):
        if self.conn:
            try:
                self.conn.close()
            except:
                pass
        try:
            self.conn = remote(HOST, PORT, timeout=5)
            return True
        except Exception as e:
            log.error(f"Connection error: {e}")
            time.sleep(1)
            return False

    def ensure_connection(self):
        for _ in range(MAX_RETRIES):
            if self.connect():
                return True
            time.sleep(1)
        return False

    def refresh_connection(self):
        self.request_count += 1
        if self.request_count >= RECONNECT_EVERY:
            self.ensure_connection()
            self.request_count = 0

    def get_encrypted_message(self):
        for _ in range(MAX_RETRIES):
            try:
                if not self.ensure_connection():
                    continue

                # Clear any pending output
                try:
                    self.conn.clean()
                except:
                    pass

                self.conn.sendline(b"1")
                time.sleep(SLEEP_TIME)
                self.conn.sendline(b"poodle")
                time.sleep(SLEEP_TIME)
                self.conn.sendline(b"1")
                time.sleep(SLEEP_TIME)

                data = self.conn.recvuntil(b"selection:", timeout=5)
                for line in data.split(b'\n'):
                    if b"banner that reads: " in line:
                        ct = line.split(b"banner that reads: ")[1].strip()
                        return ct.decode()

            except Exception as e:
                log.error(f"Error getting encrypted message: {e}")
                time.sleep(1)
                self.ensure_connection()
        return None

    def submit_ciphertext(self, ct):
        for _ in range(MAX_RETRIES):
            try:
                if not self.ensure_connection():
                    continue

                self.refresh_connection()

                # Clear any pending output
                try:
                    self.conn.clean()
                except:
                    pass

                self.conn.sendline(b"2")
                time.sleep(SLEEP_TIME)
                self.conn.sendline(ct.encode())
                time.sleep(SLEEP_TIME)

                response = self.conn.recvuntil(b"selection:", timeout=5)
                return b"Valid" in response

            except Exception as e:
                log.error(f"Error submitting ciphertext: {e}")
                time.sleep(1)
                self.ensure_connection()
        return False

    def decrypt_byte(self, ct_blocks, target_block, known_text):
        ct_bytes = base64.b64decode(ct_blocks)
        blocks = [ct_bytes[i:i+16] for i in range(0, len(ct_bytes), 16)]

        # Create modified ciphertext
        new_blocks = blocks[:target_block] + [blocks[target_block-1]] + blocks[target_block+1:]
        modified_ct = base64.b64encode(b''.join(new_blocks)).decode()

        if self.submit_ciphertext(modified_ct):
            pad_byte = 16 - (len(known_text) % 16)
            decrypted_byte = pad_byte ^ blocks[target_block-1][-1] ^ blocks[target_block][-1]
            return decrypted_byte
        return None

    def process_block(self, block_num):
        if str(block_num) in self.decrypted_bytes:
            log.info(f"Block {block_num} already decrypted")
            return

        ct = self.get_encrypted_message()
        if not ct:
            log.error(f"Failed to get encrypted message for block {block_num}")
            return

        known_text = b''
        ct_blocks = ct

        for pos in range(15, -1, -1):
            byte = self.decrypt_byte(ct_blocks, block_num, known_text)
            if byte is not None:
                known_text = bytes([byte]) + known_text
                self.decrypted_bytes[str(block_num)] = known_text.hex()
                self.save_progress()

                # Print decrypted byte info
                char_repr = chr(byte) if 32 <= byte <= 126 else '?'
                log.info(f"Block {block_num}, Pos {pos}: {hex(byte)} ({char_repr})")

                # Check for flag pattern
                text = known_text.decode('ascii', errors='ignore')
                if 'flag{' in text:
                    flag_start = text.index('flag{')
                    potential_flag = text[flag_start:text.find('}', flag_start) + 1]
                    log.success(f"Found flag pattern: {potential_flag}")

def main():
    log.info("Starting optimized POODLE attack...")
    attacker = PoodleAttack()

    # Process blocks sequentially (more reliable than parallel in this case)
    target_blocks = range(2, 8)  # Adjust based on message structure

    for block in target_blocks:
        log.info(f"Processing block {block}")
        try:
            attacker.process_block(block)
        except Exception as e:
            log.error(f"Error processing block {block}: {e}")
            continue

